import React, {useEffect, useState } from 'react';
import { getWarehouseProductInfo } from '../data/dataFetching';

import { useParams } from 'react-router-dom';

function ProductDetailsInventory() {

    const { id } = useParams();

    const [warehouseProductInfo, setWarehouseProductInfo] = useState([]);
       
    useEffect(() => {
        getWarehouseProductInfo(id).then(data => setWarehouseProductInfo(data));
        }, []);

    return (
        <table>
            <thead>
                <tr>
                    <th>Warehouse</th>
                    <th>Quantity</th>
                    <th>Location</th>
                    
                </tr>
            </thead>

            <tbody>
                {warehouseProductInfo.map(warehouseProductInfo => (
                    <tr key={warehouseProductInfo.warehouse_id}>
                        <td><a href={'/warehouses/warehouse-info/' + warehouseProductInfo.warehouse_id}>{warehouseProductInfo.warehouse_name}</a></td>
                        <td>{warehouseProductInfo.w_quantity}</td>
                        <td>{warehouseProductInfo.location}</td>
                    
                    </tr>
                ))}
            </tbody>

        </table>
    )
}

export default ProductDetailsInventory;
